query.base:
FROM metrics-gcp.cloudsql_postgresql.otel-*
| WHERE gcp.resource_type == "cloudsql_database"
// Two windows in one pass:
//  - the PostgreSQL engine marker (num_backends) over the whole rule window (24h), so an
//    instance that has just stopped (and no longer emits num_backends) stays in scope;
//  - the current state from the last 15 minutes only. Keep this >= 10-15 minutes to
//    tolerate the 3-5+ minute Cloud Monitoring ingestion delay.
// Older documents are only needed for the marker, so everything else is dropped before
// aggregating. One row per instance, no per-minute buckets: cheap on large fleets.
| WHERE `@timestamp` >= NOW() - 15 minutes
     OR `cloudsql.googleapis.com/database/postgresql/num_backends` IS NOT NULL
| EVAL recent = `@timestamp` >= NOW() - 15 minutes
// Latest value by timestamp across all documents, so a stale series fragment can never
// win (unlike MAX(LAST_OVER_TIME()) per series). attributes.state is only meaningful on
// the instance_state document whose value is 1.
| STATS pg_total = COUNT(`cloudsql.googleapis.com/database/postgresql/num_backends`),
        state = LAST(attributes.state, `@timestamp`) WHERE recent AND `cloudsql.googleapis.com/database/instance_state` == 1,
        up = LAST(`cloudsql.googleapis.com/database/up`, `@timestamp`) WHERE recent AND `cloudsql.googleapis.com/database/up` IS NOT NULL,
        last_seen = MAX(`@timestamp`) WHERE recent
    BY database_id

breach.segment:
// PostgreSQL engine marker, and the instance reported in the signal window
WHERE pg_total > 0 AND last_seen IS NOT NULL
| EVAL last_seen = DATE_TRUNC(1 minute, last_seen)
| WHERE up IS NOT NULL OR state IS NOT NULL
// Breach: the instance is not serving (up = 0) or is in a non-RUNNING state.
// MAINTENANCE is Google-scheduled and expected; it only alerts if it outlasts the
// alert delay. If owners intentionally stop instances (RUNNABLE) or you want to ignore
// maintenance, append e.g. | WHERE COALESCE(state, "") NOT IN ("RUNNABLE", "MAINTENANCE")
| WHERE up == 0 OR (state IS NOT NULL AND state != "RUNNING")
| EVAL reason = CASE(
    state IS NOT NULL AND state != "RUNNING", CONCAT("instance_state=", state),
    "up=0 (not serving while RUNNING)")
| KEEP database_id, state, up, reason, last_seen
| SORT database_id
| LIMIT 100
